/**
 * The authoritative link types.
 *
 * Palantir keeps a link type in the ontology, not in the module that happens to talk to one
 * provider: a link is a statement about the business, and a data source only supplies its
 * instances. This file is that single authority, including the order the graph is built in.
 *
 * A null cardinality means the declaration in service carried no such key. That is not cosmetic:
 * the compiler digests a link definition, and writing `required: false` where the declaration had
 * nothing changes the digest, so a synthesised link must omit the key too.
 */
export type LinkEnd = { type: string; name: string; many: boolean | null; required: boolean | null };
export type LinkTypeDeclaration = {
  /** Position in the graph, so it can be synthesised from this table alone. */
  order: number;
  apiName: string;
  description: string | null;
  from: LinkEnd;
  to: LinkEnd;
  roles: readonly string[] | null;
  properties: Record<string, unknown> | null;
};

