export const LINK_TYPE_BY_API_NAME: ReadonlyMap<string, LinkTypeDeclaration> = new Map(LINK_TYPES.map(link => [link.apiName, link]));

const sameEnd = (declared: LinkEnd, actual: { type: string; name: string; many?: boolean; required?: boolean }) =>
  declared.type === actual.type && declared.name === actual.name
  && (declared.many === null || declared.many === !!actual.many)
  && (declared.required === null || declared.required === !!actual.required);

/** A link whose shape in the document differs from the authoritative declaration. */
export function linkTypeDrift(links: readonly { id: string; from: { type: string; name: string; many?: boolean; required?: boolean }; to: { type: string; name: string; many?: boolean; required?: boolean } }[]) {
  const drift: string[] = [];
  const seen = new Set<string>();
  for (const link of links) {
    const declared = LINK_TYPE_BY_API_NAME.get(link.id);
    if (!declared) { drift.push(`undeclared link: ${link.id}`); continue; }
    seen.add(link.id);
    if (!sameEnd(declared.from, link.from) || !sameEnd(declared.to, link.to)) drift.push(`shape drift: ${link.id}`);
  }
  for (const apiName of LINK_TYPE_BY_API_NAME.keys()) if (!seen.has(apiName)) drift.push(`missing link: ${apiName}`);
  return drift;
}
